head.script:
scwin.onpageload = function() {

};

scwin.btn1_onkeydown = function (e) {
    console.log("tab test!");
};

scwin.auto1_oneditenter = function () {
    console.log("tab next!");
};

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#btn1', 'key-combo', {
			combo: 'TAB'
		});
	}	
	scwin.checkVal = function() {
		console.log(WebSquare.wUnit.getDomById('ipt1').classList.contains('w2input_focus'))
		return WebSquare.wUnit.getDomById('ipt1').classList.contains('w2input_focus');
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn1').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
